patch_proposal:manual-swe-runs5-20260224.content:
{
  "summary": "Require >=5 real runs in swe_truth_check before validated verdict",
  "patches": [
    {
      "kind": "repo_patch",
      "scope": "repo",
      "rationale": "Prevent theoretical validation with too few runs; require stronger factual evidence.",
      "risk": "low",
      "tests": ["npm run -s build"],
      "success_metrics": ["swe_truth_check includes runs_count >= 5 gate", "build passes"],
      "rollback_plan": "Revert patch by git apply -R on stored diff",
      "diff": "diff --git a/src/index.ts b/src/index.ts
--- a/src/index.ts
+++ b/src/index.ts
@@ -6591,16 +6591,19 @@
-      const metricsKnown = selected
-        ? Number((selected as any)?.metrics?.runs_count ?? 0) > 0
-        : false;
+      const runsCount = selected
+        ? Number((selected as any)?.metrics?.runs_count ?? 0)
+        : 0;
+      const metricsKnown = runsCount > 0;
       const evidenceStatus = {
         metrics_known: metricsKnown,
+        runs_count: runsCount,
         benchmark_tasks_done: grouped.done,
         benchmark_tasks_total: grouped.todo + grouped.doing + grouped.done + grouped.blocked,
       };
       const verdict = (
         evidenceStatus.metrics_known &&
+        evidenceStatus.runs_count >= 5 &&
         evidenceStatus.benchmark_tasks_done >= 3 &&
         metaDepth.pending < 2000
       ) ? "validated" : "insufficient_evidence";
"
    }
  ]
}

